<script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {PackageX,SlidersHorizontal} from 'lucide-vue-next';import {api,idr} from '../api';import type {Product} from '../stores';import ProductCard from '../components/ProductCard.vue';import {useCart,useSession,useUi} from '../stores';const route=useRoute(),router=useRouter(),products=ref<Product[]>([]),categories=ref<any[]>([]),loading=ref(true),error=ref(''),search=ref(String(route.query.search??'')),sort=ref(String(route.query.sort??'newest')),category=ref(String(route.query.category??'')),minPrice=ref(0),maxPrice=ref(10000000),inStock=ref(false),page=ref(1),pages=ref(1),total=ref(0),mobileFilters=ref(false);const cart=useCart(),session=useSession(),ui=useUi();let timer:number;async function load(){loading.value=true;error.value='';const q=new URLSearchParams({limit:'9',sort:sort.value,page:String(page.value),minPrice:String(minPrice.value),maxPrice:String(maxPrice.value)});if(search.value)q.set('search',search.value);if(category.value)q.set('category',category.value);if(inStock.value)q.set('inStock','true');router.replace({query:Object.fromEntries(q)});try{const result=await api<{items:Product[],page:number,pages:number,total:number}>(`/products?${q}`);products.value=result.items;pages.value=result.pages;total.value=result.total}catch(e:any){error.value=e.message}finally{loading.value=false}}function queue(){clearTimeout(timer);timer=window.setTimeout(()=>{page.value=1;load()},250)}function reset(){search.value='';category.value='';minPrice.value=0;maxPrice.value=10000000;inStock.value=false;sort.value='newest';queue()}async function add(id:string){if(!session.user)return router.push('/login');try{await cart.add(id);ui.toast('Added to your shopping bag');ui.cartOpen=true}catch(e:any){ui.toast(e.message,'error')}}onMounted(async()=>{try{categories.value=await api('/categories')}catch{}load()});watch([search,sort,category,minPrice,maxPrice,inStock],queue);watch(page,load);watch(()=>route.query.search,v=>{if(String(v??'')!==search.value)search.value=String(v??'')});watch(()=>route.query.category,v=>{if(String(v??'')!==category.value)category.value=String(v??'')});watch(()=>route.query.sort,v=>{if(v&&String(v)!==sort.value)sort.value=String(v)});</script>
<template><main class="catalog-page"><div class="container"><header class="catalog-header"><div><h1>{{category?categories.find(c=>c.slug===category)?.name??'Collection':'All Collections'}}</h1><p>Showing {{total}} available premium items</p></div><div><label>Sort by:</label><select v-model="sort"><option value="newest">Newest Arrivals</option><option value="price_asc">Price: Low to High</option><option value="price_desc">Price: High to Low</option><option value="name">Name A–Z</option></select><button class="filter-toggle" @click="mobileFilters=!mobileFilters"><SlidersHorizontal :size="16"/> Filters</button></div></header><div class="catalog-layout"><aside class="filter-panel" :class="{open:mobileFilters}"><header><b>Filters</b><button @click="reset">Reset All</button></header><label class="search-field">Search<input v-model="search" placeholder="Product name or keyword"/></label><fieldset><legend>Category</legend><label><input v-model="category" type="radio" value=""/> All Categories</label><label v-for="c in categories" :key="c.id"><input v-model="category" type="radio" :value="c.slug"/> {{c.name}}</label></fieldset><fieldset><legend>Price Range</legend><label class="range-label"><span>Minimum</span><b>{{idr(minPrice)}}</b></label><input v-model.number="minPrice" type="range" min="0" max="10000000" step="100000"/><label class="range-label"><span>Maximum</span><b>{{idr(maxPrice)}}</b></label><input v-model.number="maxPrice" type="range" min="0" max="10000000" step="100000"/></fieldset><fieldset><legend>Availability</legend><label><input v-model="inStock" type="checkbox"/> In Stock Only</label></fieldset></aside><section class="catalog-results"><p v-if="error" class="alert error">{{error}}</p><div v-if="loading" class="product-grid three"><div v-for="i in 6" class="skeleton product-skeleton"/></div><div v-else-if="products.length" class="product-grid three"><ProductCard v-for="p in products" :key="p.id" :product="p" @add="add"/></div><div v-else class="empty-state"><PackageX :size="48"/><h3>No matching products found</h3><p>Try resetting your filters or adjusting your search term.</p><button class="btn-primary" @click="reset">Reset Filters</button></div><nav v-if="pages>1" class="pagination" aria-label="Catalog pages"><button :disabled="page===1" @click="page--">Previous</button><button v-for="p in pages" :class="{active:page===p}" @click="page=p">{{p}}</button><button :disabled="page===pages" @click="page++">Next</button></nav></section></div></div></main></template>
